def top_artifacts(run_dirs: Iterable[str], k: int, lower_is_better: bool = True) -> list[dict]:
    """Top-k distinct ok artifacts across runs by dev value."""
    cands: dict[str, dict] = {}
    for rd in run_dirs:

p = os.path.join(rd, "events.jsonl")
        if not os.path.exists(p):
