        return BwrapLauncher(bw_path, extra_ro=kw.get("extra_ro"), extra_args=kw.get("extra_args"))
    if kind == "none":
        return NoSandboxLauncher(quiet=kw.get("quiet", False))
    raise ValueError(f"unknown sandbox kind {kind!r}")


