def rsi_root() -> str:
    return os.environ.get("RSI_ROOT") or os.environ.get("R") or "/scratch/user/rsi"

def service_url(name: str, ports_file: str | None = None) -> str:
    """Resolve a service URL from $RSI_ROOT/run/ports.json (int port, "host:port", URL or {host, port})."""
    pf = ports_file or os.path.join(rsi_root(), "run", "ports.json")
    ports = read_json(pf, {}) or {}
    v = ports.get(name)
    if v is None:
        raise SystemExit(f"service {name!r} not found in {pf}")
    if isinstance(v, dict):
        if v.get("url"):
            return v["url"]
        return f"http://{v.get('host', '127.0.0.1')}:{v['port']}"
    if isinstance(v, int) or (isinstance(v, str) and v.isdigit()):
        return f"http://127.0.0.1:{v}"
    return v if str(v).startswith("http") else f"http://{v}"


def agent_gateway_url(h: dict) -> str:
    """Gateway for sandboxed agents: ports.json key ``gateway_agent`` (a gateway instance whose only inbound
    token is $R/run/agent_token), falling back to ``gateway`` only if ``allow_main_gateway`` is set."""
    key = h.get("gateway_ports_key", "gateway_agent")
    try:
        return service_url(key, h.get("ports_file"))
    except SystemExit:
        if h.get("allow_main_gateway"):
            return service_url("gateway", h.get("ports_file"))
        raise


