def load_policy(name: str) -> type:
    """Find the Policy class for ``name`` in ``rsi.policies.<name>``."""
    mod = importlib.import_module(f"rsi.policies.{name}")
    cls = getattr(mod, "POLICY", None)
    if cls is not None:
        return cls
