_REGISTRY: dict[str, type] = {}

def register(cls: type) -> type:
    """Class decorator: ``@register`` makes ``get_task(cls.name)`` work."""
    _REGISTRY[cls.name] = cls
    return cls


def get_task(name: str, **kw) -> Task:
    if name not in _REGISTRY:
        # lazy-import the known task packages so their @register runs
        import importlib

        for mod in ("rsi.tasks.nanochat", "rsi.tasks.muar"):
            try:
                importlib.import_module(mod)
            except ImportError:
                pass
    if name not in _REGISTRY:
        # family lookup: "muar/xyz" -> registered "muar" factory taking name=
        fam = name.split("/", 1)[0]
        if fam in _REGISTRY and fam != name:
            return _REGISTRY[fam](name=name, **kw)
        raise KeyError(f"unknown task {name!r}; registered: {sorted(_REGISTRY)}")
    return _REGISTRY[name](**kw)

def _balanced(rng, L, K):
    """Random balanced bracket string of even length L over K bracket types (token ids 0..2K-1)."""
    out, stack = [], []
    for i in range(L):
        remaining = L - i
        can_open = len(stack) < remaining - 1 if remaining > 1 else False
        if stack and (not can_open or rng.random() < 0.5):
            out.append(2 * stack.pop() + 1)
        else:
            t = int(rng.integers(0, K))
            stack.append(t)
            out.append(2 * t)
    return out


def _is_balanced(s, K):
    stack = []
    for tok in s:
        if tok % 2 == 0:
            stack.append(tok // 2)
        elif not stack or stack.pop() != tok // 2:
            return False
    return not stack


