    """Curves s_t = s0 * exp(-rate * t) + noise, s0 = 1, s_ref = 0."""
    out = {}
    for t in tasks:
        out[t] = {}
        for s in seeds:
            out[t][str(s)] = [float(math.exp(-rate * (i + 1)) + noise * rng.normal()) for i in range(n)]
