const fmtV = v => v == null || !isFinite(v) ? "n/a" : (+v).toFixed(4);
// number of items with acc(item) <= T in an array sorted by acc
function upto(arr, T, acc) { let lo = 0, hi = arr.length; while (lo < hi) { const m = (lo + hi) >> 1; if (acc(arr[m]) <= T) lo = m + 1; else hi = m; } return lo; }
function hashJitter(s) { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return ((h >>> 0) % 1000) / 1000 - 0.5; }
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

/* ===================== model ===================== */
let M = null;          // built model
let T = 0;             // replay time, seconds since first event
let playing = false, speed = 120, lastFrame = null, dirty = true;
let xMode = "time", yMode = "zoom";

function parseJSONL(text) {
  const out = []; let bad = 0;
  for (const line of text.split(/\r?\n/)) {
    const s = line.trim(); if (!s) continue;
    try { const e = JSON.parse(s); if (e && typeof e.t === "number" && e.ev) out.push(e); else bad++; } catch { bad++; }
  }
  out.forEach((e, i) => e._i = i);
  out.sort((a, b) => a.t - b.t || a._i - b._i);
  return { events: out, bad };
}

function guessRole(id) {
  if (id === "orchestrator") return "orchestrator";
  if (id === "evald") return "evald";
  if (id.includes("lessons")) return "lessons-writer";
  if (id.includes("/")) return "subagent";
  if (id.startsWith("thread")) return "researcher";
  return "service";

}

function build(events) {
  const t0 = events[0].t, rel = e => e.t - t0;
  const runs = new Map(), agents = new Map();
  const tools = [], llms = [], msgs = [], jobs = [], decisions = [], evals = [], audits = [], marks = [], feed = [];
  const key = (run, a) => `${run}::${a}`;
  const ensureRun = e => {
    let r = runs.get(e.run);
    if (!r) { r = { id: e.run, gen: e.gen ?? 0, start: rel(e), end: rel(e), meta: null, endEv: null, idx: runs.size, lanes: [], budget: null, metric: null }; runs.set(e.run, r); }
    r.end = Math.max(r.end, rel(e));
    return r;
  };
  const ensureAgent = (run, id, parent, t, gen) => {
    if (!id) return null;
    const k = key(run, id); let a = agents.get(k);
    if (!a) { a = { key: k, run, id, parent: parent ?? null, role: guessRole(id), model: null, spawn: t, end: null, implicit: true, gen }; agents.set(k, a); }
