def load(path):
    evs = []
    bad = 0
    with open(path, encoding="utf-8") as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                e = json.loads(line)
            except json.JSONDecodeError:
                bad += 1
                continue
            if isinstance(e, dict) and "t" in e and "ev" in e:
                e["_i"] = i
                evs.append(e)
            else:
                bad += 1
    evs.sort(key=lambda e: (e["t"], e["_i"]))
