def split_think(text):
    t = text
    for s in ("<|im_end|>", "<|endoftext|>"):
        t = t.split(s)[0]
    if "</think>" in t:
        r, c = t.split("</think>", 1)
        return r.replace("<think>", "").strip(), c.strip()
    return t.replace("<think>", "").strip(), ""          # never closed the think block (ran out of tokens)


